    o = observation.get("opponent_position", None)
    rs = observation.get("resources", [])
    obs = observation.get("obstacles", [])
    sp = s if isinstance(s, (list, tuple)) and len(s) >= 2 else (0, 0)
    sx, sy = int(sp[0]), int(sp[1])

    def pos(v):
        if isinstance(v, dict):
            if "x" in v and "y" in v: return (v["x"], v["y"])
            for k in ("pos", "position", "loc", "location"):
                p = v.get(k)
                if isinstance(p, (list, tuple)) and len(p) >= 2: return (p[0], p[1])
        elif isinstance(v, (list, tuple)) and len(v) >= 2:
            return (v[0], v[1])
        return None

    def nearest(items):
        best = None
        bd = 10**9
        for it in items:
            p = pos(it)
            if p is None: 
                continue
            d = abs(p[0] - sx) + abs(p[1] - sy)
            if d < bd:
                bd = d
                best = p
        return best

    def blocked(x, y):
        if x < 0 or y < 0 or (w and x >= w) or (h and y >= h):
            return True
        for it in obs:
            p = pos(it)
            if p and p[0] == x and p[1] == y:
                return True
        return False

    t = nearest(rs)
    if t is None:
        tx, ty = (w - 1 - sx, h - 1 - sy) if w and h else (1, 0)
    else:
        tx, ty = int(t[0]), int(t[1])

    moves = []
    dx = 1 if tx > sx else -1 if tx < sx else 0
    dy = 1 if ty > sy else -1 if ty < sy else 0
    cand = [(dx, 0), (0, dy), (dx, dy), (dx, -dy), (0, 0)]
    for m in cand:
        x, y = sx + m[0], sy + m[1]
        if not blocked(x, y):
            moves.append(m)

    if o is not None:
        p = pos(o)
        if p is not None:
            ox, oy = int(p[0]), int(p[1])
            moves.sort(key=lambda m: abs((sx + m[0]) - tx) + abs((sy + m[1]) - ty) + (0 if abs(sx + m[0] - ox) + abs(sy + m[1] - oy) > 1 else 2))
    if moves:
        return [int(moves[0][0]), int(moves[0][1])]
    for m in ((1, 0), (0, 1), (-1, 0), (0, -1), (0, 0)):
        if not blocked(sx + m[0], sy + m[1]):
            return [m[0], m[1]]
    return [0, 0]

